type userPropKey struct{ userId, key string }

type MockedUserPropsRepo struct {
	model.UserPropsRepository
	data map[userPropKey]string
	err  error
}

func (p *MockedUserPropsRepo) init() {
	if p.data == nil {
		p.data = make(map[userPropKey]string)
	}
}

func (p *MockedUserPropsRepo) Put(userId, key, value string) error {
	if p.err != nil {
		return p.err
	}
	p.init()
	p.data[userPropKey{userId, key}] = value
	return nil
}

func (p *MockedUserPropsRepo) Get(userId, key string) (string, error) {
	if p.err != nil {
		return "", p.err
	}
	p.init()
	if v, ok := p.data[userPropKey{userId, key}]; ok {
		return v, nil
	}
	return "", model.ErrNotFound
}

func (p *MockedUserPropsRepo) Delete(userId, key string) error {
	if p.err != nil {
		return p.err
	}
	p.init()
	if _, ok := p.data[userPropKey{userId, key}]; ok {
		delete(p.data, userPropKey{userId, key})
		return nil
	}
	return model.ErrNotFound
}

func (p *MockedUserPropsRepo) DefaultGet(userId, key, defaultValue string) (string, error) {
	if p.err != nil {
		return "", p.err
	}
	p.init()
	v, err := p.Get(userId, key)
	if err == model.ErrNotFound {
		return defaultValue, nil
	}
	return v, err
}

